    // Check for invalid inputs
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("All parameters must be non-null");
    }

    // Initialize the circulator
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop);

    // Traverse the component based on direction
    if (dir == NORTH) {
        for (Node node = circulator.getCirculatorNode(); node != null; node = node.getNext()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
    } else if (dir == SOUTH) {
        for (Node node = circulator.getCirculatorNode(); node != null; node = node.getPrevious()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
    } else if (dir == EAST) {
        for (Node node = circulator.getCirculatorNode(); node != null; node = node.getNext()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
    } else if (dir == WEST) {
        for (Node node = circulator.getCirculatorNode(); node != null; node = node.getPrevious()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
    }

    // Return the stop node if no valid node is found
    return circulator;
}

