private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label minLabel to the bucket with label 0.
    // Clear the bucket with label minLabel. Update the labeling accordingly.
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            Collections.swap(bucketsByLabel, 0, i);
            labels.set(i, 0);
            break;
        }
    }

    // Clear the bucket with label minLabel.
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        } else {
            bucketsByLabel.set(i, Collections.emptySet());
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || bucketsByLabel.size() == 0 || labels.size() == 0) {
        throw new IllegalArgumentException("Input lists cannot be null or empty.");
    }

    int destinedLabel = 0;
    for (int label : labels) {
        if (label < minLabel) {
            continue; // Skip vertices in non-empty buckets
        }
        if (!bucketsByLabel.get(label).isEmpty()) {
            destinedLabel++;
        }
    }

    bucketsByLabel.remove(minLabel);
    for (int label : labels) {
        if (label < minLabel) {
            continue; // Skip vertices in non-empty buckets
        }
        if (label >= destinedLabel) {
            Set<Integer> newBucket = new HashSet<>();
            newBucket.add(label);
            bucketsByLabel.add(newBucket);
        }
    }
}

