            } else if (f.endsWith(".jar") || f.endsWith(".war") || f.endsWith(".ear")) {
                URL jarURL = f.toURI().toURL();
                cpV.add(jarURL);
            }
        }
    } catch (Exception e) {
        System.err.println("Error adding classpath for directory " + dir);
        e.printStackTrace();
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File file = new File(dir);
        URL url = file.toURI().toURL();
        cpV.add(url);
    } catch (Exception e) {
        e.printStackTrace();
    }
}

